package com.bank.letterstats;

import java.util.*;
import java.util.logging.*;

public class VowelConsonantDemo {
    private static final Logger log = Logger.getLogger("LetterStats");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        LetterStatsService service = new LetterStatsService();
        Map<Boolean, Long> stats = service.countVowelsConsonants("Rajesh Kumar");
        log.info(() -> "vowels=" + stats.get(true) + " consonants=" + stats.get(false));
    }
}

// ─── Would be in service/LetterStatsService.java ───
class LetterStatsService {
    Map<Boolean, Long> countVowelsConsonants(String s) {
        return s.chars()
            .mapToObj(c -> Character.toLowerCase((char) c))
            .filter(Character::isLetter)                          // ignore digits/spaces
            .collect(java.util.stream.Collectors.partitioningBy(
                c -> "aeiou".indexOf(c) >= 0,                     // true = vowel
                java.util.stream.Collectors.counting()));
    }
}
